# Generated by build.py from recipe.yml for recipe https-serve-a-pfx-certificate. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site2' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site2/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
cmd /c 'openssl pkcs12 -export -out server.pfx -inkey server.key -in server.pem -passout pass:s3cret'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pfx', '--cert-type', 'P12', '--pass', 's3cret', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --cacert server.pem https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
